fn putmask(a: Vec<f32>, mask: Vec<bool>, values: Vec<f32>) -> Vec<f32> {
    assert_eq!(a.len(), mask.len(), "mask must have same length as input array");
    assert!(!values.is_empty(), "values must be non-empty");

    let vlen = values.len();
    let mut result = a;

    for (i, m) in mask.iter().enumerate() {
        if *m {
            result[i] = values[i % vlen];
        }
    }

    result
}